import{_ as t,o as e,c as i,a2 as l}from"./chunks/framework.z3u3TMv0.js";const k=JSON.parse('{"title":"安裝 LocalAI","description":"使用 LocalAI 提供 OpenAI 兼容 API，從 Docker 或二進制安裝後連接 MiniTavern。","frontmatter":{"title":"安裝 LocalAI","description":"使用 LocalAI 提供 OpenAI 兼容 API，從 Docker 或二進制安裝後連接 MiniTavern。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"安裝 LocalAI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"使用 LocalAI 提供 OpenAI 兼容 API，從 Docker 或二進制安裝後連接 MiniTavern。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/localai/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/localai/install"}]]},"headers":[],"relativePath":"zh-TW/localai/install.md","filePath":"zh-TW/localai/install.md","lastUpdated":1787224147000}'),r={name:"zh-TW/localai/install.md"};function n(o,a,s,h,d,c){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="安裝與連接-localai" tabindex="-1">安裝與連接（LocalAI） <a class="header-anchor" href="#安裝與連接-localai" aria-label="Permalink to &quot;安裝與連接（LocalAI）&quot;">​</a></h1><p><a href="https://localai.io/" target="_blank" rel="noreferrer">LocalAI</a> 是本地的 OpenAI 兼容 API 網關，可對接多種後端。適合已經熟悉 Docker、或希望「一個兼容層接多種模型」的用戶。</p><h2 id="快速啟動-docker-示例" tabindex="-1">快速啟動（Docker 示例） <a class="header-anchor" href="#快速啟動-docker-示例" aria-label="Permalink to &quot;快速啟動（Docker 示例）&quot;">​</a></h2><p>具體鏡像名與端口以 <a href="https://localai.io/" target="_blank" rel="noreferrer">官方文檔</a> 為準，示意：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local-ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localai/localai:latest</span></span></code></pre></div><p>首次需按文檔放入或拉取模型；確認本機可訪問：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8080/v1/models</span></span></code></pre></div><h2 id="局域網" tabindex="-1">局域網 <a class="header-anchor" href="#局域網" aria-label="Permalink to &quot;局域網&quot;">​</a></h2><ul><li>容器端口映射到宿主機後，防火牆放行 <strong>8080</strong>（或你映射的端口）。</li><li>手機使用：<code>http://YOUR_PC_IP:8080/v1</code>。</li><li>若容器只綁定了錯誤網卡，檢查 Docker 端口發佈與宿主機防火牆。</li></ul><h2 id="給-minitavern" tabindex="-1">給 MiniTavern <a class="header-anchor" href="#給-minitavern" aria-label="Permalink to &quot;給 MiniTavern&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填寫</th></tr></thead><tbody><tr><td>模型平臺</td><td>自定義（OpenAI 兼容）</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:8080/v1</code></td></tr><tr><td>API Key</td><td>按 LocalAI 是否啟用鑑權填寫</td></tr><tr><td>模型名</td><td>與 LocalAI 中配置的 model id 一致</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="/ultra_guides/zh-TW/connect-app/minitavern">在 MiniTavern 中配置</a> · <a href="/ultra_guides/zh-TW/local/tools">工具總覽</a> · <a href="/ultra_guides/zh-TW/troubleshoot">排錯</a></p>',13)])])}const u=t(r,[["render",n]]);export{k as __pageData,u as default};
